var t={en:`An agent removed secure credential storage and API auth, then connected mobile and push systems directly to the server database.`,ua:`Агент прибрав безпечне зберігання даних доступу та авторизацію API, а потім під’єднав mobile і push напряму до серверної БД.`};var r={en:[`Remove mobile→primarydb and push→primarydb shortcuts.`,`Restore mobile→secure and api→auth.`,`Add a retry-safe sync queue with token expiry handling.`],ua:[`Прибери mobile→primarydb і push→primarydb.`,`Віднови mobile→secure та api→auth.`,`Додай безпечні повтори синхронізації й обробку закінчення токена.`]};var n=[{en:`Only API mediates remote domain storage.`,ua:`Лише API забезпечує доступ до серверних даних.`},{en:`Secure credentials and request authentication are represented.`,ua:`Захищені дані доступу й автентифікація присутні.`}];var i={remove:[`mobile->secure`,`api->auth`],add:[{from:`mobile`,to:`primarydb`,kind:`data`,label:`Intentional defect / Навмисна помилка`},{from:`push`,to:`primarydb`,kind:`data`,label:`Intentional defect / Навмисна помилка`}]};var d={scenario:t,tasks:r,checks:n,mutations:i};export{n as checks,d as default,i as mutations,t as scenario,r as tasks};